// Comparison pairs from the presentation
var OCA_PAIRS = [
  {label:'Light Summer vs Light Spring',   seasons:['Light Summer','Light Spring']},
  {label:'Soft Summer vs Soft Autumn',     seasons:['Soft Summer','Soft Autumn']},
  {label:'True Winter vs True Summer',     seasons:['True Winter','True Summer']},
  {label:'True Spring vs True Autumn',     seasons:['True Spring','True Autumn']},
  {label:'Dark Autumn vs Dark Winter',     seasons:['Dark Autumn','Dark Winter']},
  {label:'Bright Winter vs Bright Spring', seasons:['Bright Winter','Bright Spring']}
];

// Season groups for tabs
var OCA_GROUPS = {
  Summer: ['Light Summer','True Summer','Soft Summer'],
  Winter: ['Bright Winter','True Winter','Dark Winter'],
  Autumn: ['Soft Autumn','True Autumn','Dark Autumn'],
  Spring: ['Light Spring','True Spring','Bright Spring']
};


// ══════════════════════════════════════════════════
// ONLINE COLOUR ANALYSIS — State & Functions
// ══════════════════════════════════════════════════
var ocaPhoto       = null;   // base64 uploaded photo
var ocaTab         = 'draping';
var ocaSeasonTab   = 'Summer';
var ocaCompSeasons = ['Light Summer', 'Light Spring', ''];  // up to 3

function setOcaTab(tab) {
  ocaTab = tab;
  document.querySelectorAll('[id^="oca-tab-"]').forEach(function(b){ b.classList.remove('on'); });
  var tb = document.getElementById('oca-tab-'+tab); if(tb) tb.classList.add('on');
  renderOca();
  if (tab==='fundamentals') setTimeout(setupOcaDrag, 100);
}

function setOcaSeasonTab(group) {
  ocaSeasonTab = group;
  document.querySelectorAll('[id^="oca-stab-"]').forEach(function(b){ b.classList.remove('on'); });
  var tb = document.getElementById('oca-stab-'+group); if(tb) tb.classList.add('on');
  renderOcaSeasons();
}

function ocaPhotoUpload(input) {
  var file = input.files[0]; if(!file) return;
  var reader = new FileReader();
  reader.onload = function(e) {
    ocaPhoto = e.target.result;
    // update all photo previews
    document.querySelectorAll('.oca-upload-preview').forEach(function(img){
      img.src = ocaPhoto; img.style.display='block';
    });
    document.querySelectorAll('.oca-upload-placeholder').forEach(function(d){
      d.style.display='none';
    });
    renderOca();
  };
  reader.readAsDataURL(file);
}

function ocaPhotoClear() {
  ocaPhoto = null;
  document.getElementById('oca-photo-input').value = '';
  renderOca();
}

// ── Render a single season palette card ──
function renderOcaPalette(seasonName, size) {
  // size: 'full' = full page card, 'compare' = compact for comparison
  var season = OCA_SEASONS[seasonName];
  if (!season) return '';
  var isCompare = (size === 'compare');
  var swSize    = isCompare ? 80 : 110;
  var photoSize = isCompare ? 44 : 60;

  var swatches = season.swatches.map(function(sw) {
    var textCol = isLightColour(sw.hex) ? '#333' : '#fff';
    var photoHtml = ocaPhoto
      ? '<img src="'+ocaPhoto+'" style="width:'+photoSize+'px;height:'+photoSize+'px;border-radius:50%;object-fit:cover;object-position:center top;border:2px solid rgba(255,255,255,0.8);position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);pointer-events:none">'
      : '<div style="width:'+photoSize+'px;height:'+photoSize+'px;border-radius:50%;border:2px dashed rgba(255,255,255,0.5);display:flex;align-items:center;justify-content:center;position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font-size:'+(isCompare?14:18)+'px">&#128247;</div>';

    return '<div style="position:relative;width:'+swSize+'px;height:'+swSize+'px;background:'+sw.hex+';border-radius:8px;overflow:hidden;flex-shrink:0;cursor:default" title="'+sw.name+'">'
      + photoHtml
      + '<div style="position:absolute;bottom:0;left:0;right:0;background:rgba(0,0,0,0.35);padding:2px 4px;text-align:center">'
      +   '<div style="font-size:9px;color:#fff;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+sw.name+'</div>'
      +   '<div style="font-size:8px;color:rgba(255,255,255,0.8)">'+sw.hex+'</div>'
      + '</div>'
      + '</div>';
  }).join('');

  return '<div class="card" style="'+(isCompare?'flex:1;min-width:0':'')+'margin-bottom:'+(isCompare?'0':'20px')+'">'
    + '<div class="ch"><div>'
    +   '<div class="ct">'+seasonName+'</div>'
    +   '<div style="font-size:11px;color:var(--muted);margin-top:2px">'+season.desc+'</div>'
    + '</div></div>'
    + '<div class="cb">'
    +   '<div style="display:flex;flex-wrap:wrap;gap:10px;justify-content:flex-start">'
    +     swatches
    +   '</div>'
    + '</div>'
    + '</div>';
}

function isLightColour(hex) {
  var r=parseInt(hex.slice(1,3),16), g=parseInt(hex.slice(3,5),16), b=parseInt(hex.slice(5,7),16);
  return (r*0.299+g*0.587+b*0.114) > 160;
}

// ── Render draping process tab ──
function renderOcaDraping() {
  return '<div class="card"><div class="ch"><div class="ct">Virtual Draping Process</div></div>'
    + '<div class="cb">'
    + '<div style="font-size:13px;color:var(--muted);margin-bottom:20px">Upload your client\'s photo above, then use the Season tabs and Comparison tool to drape colours across their features.</div>'
    + '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:16px">'
    + renderDrapingStep('1','Upload Photo','Upload a clear, front-facing photo of your client in neutral or no makeup, in natural light.','&#128247;')
    + renderDrapingStep('2','Assess Contrast','Observe the contrast between hair, skin and eyes. High, medium or low?','&#128064;')
    + renderDrapingStep('3','Warm or Cool','Compare warm (yellow/golden) vs cool (pink/blue) undertones using the season palettes.','&#127775;')
    + renderDrapingStep('4','Season Groups','Navigate to Summer, Winter, Autumn or Spring tabs to drape individual season palettes.','&#127809;')
    + renderDrapingStep('5','Compare Seasons','Use the Comparison tab to place the photo side-by-side across 2–3 seasons at once.','&#9878;')
    + renderDrapingStep('6','Confirm Result','Note which palette makes skin glow, eyes brighten and any discolouration disappear.','&#10003;')
    + '</div>'
    + '<div style="margin-top:24px;padding:16px;background:var(--warm);border-radius:10px">'
    + '<div style="font-size:12px;font-weight:700;color:var(--charcoal);margin-bottom:8px">Season Groups</div>'
    + '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px">'
    + renderSeasonGroupSummary('Summer',  ['#D4879A','#C06880','#9080B0'], 'Cool · Soft · Muted')
    + renderSeasonGroupSummary('Winter',  ['#E00080','#0040CC','#000000'], 'Cool · Clear · Vivid')
    + renderSeasonGroupSummary('Autumn',  ['#D06820','#A03020','#406030'], 'Warm · Muted · Earthy')
    + renderSeasonGroupSummary('Spring',  ['#FFAB76','#FF7733','#90C838'], 'Warm · Clear · Bright')
    + '</div>'
    + '</div>'
    + '</div></div>';
}

function renderDrapingStep(num, title, desc, icon) {
  return '<div style="background:var(--warm);border-radius:10px;padding:16px">'
    + '<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">'
    +   '<div style="width:28px;height:28px;border-radius:50%;background:var(--rose);color:#fff;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;flex-shrink:0">'+num+'</div>'
    +   '<div style="font-size:16px">'+icon+'</div>'
    +   '<div style="font-size:13px;font-weight:700;color:var(--charcoal)">'+title+'</div>'
    + '</div>'
    + '<div style="font-size:12px;color:var(--muted);line-height:1.6">'+desc+'</div>'
    + '</div>';
}

function renderSeasonGroupSummary(name, colours, desc) {
  var dots = colours.map(function(c){ return '<div style="width:16px;height:16px;border-radius:50%;background:'+c+'"></div>'; }).join('');
  return '<div style="background:#fff;border-radius:8px;padding:10px;text-align:center">'
    + '<div style="font-size:12px;font-weight:700;color:var(--charcoal);margin-bottom:6px">'+name+'</div>'
    + '<div style="display:flex;gap:4px;justify-content:center;margin-bottom:6px">'+dots+'</div>'
    + '<div style="font-size:10px;color:var(--muted)">'+desc+'</div>'
    + '</div>';
}

// ── Render seasons tab — vertical scroll, cool-vs-warm style with tally ──
var ocaSeasonVotesSub = { Summer:{}, Winter:{}, Autumn:{}, Spring:{} };

function ocaSubVote(group, i, sub) {
  if (!ocaSeasonVotesSub[group]) ocaSeasonVotesSub[group] = {};
  if (ocaSeasonVotesSub[group][i] === sub) delete ocaSeasonVotesSub[group][i];
  else ocaSeasonVotesSub[group][i] = sub;
  renderOcaSeasons();
}
function ocaSubClearVotes(group) {
  ocaSeasonVotesSub[group] = {};
  renderOcaSeasons();
}

function renderOcaSeasons() {
  var el = document.getElementById('oca-seasons-content'); if(!el) return;
  var seasons = OCA_GROUPS[ocaSeasonTab] || [];
  if (!seasons.length) { el.innerHTML = ''; return; }

  var subLabels = {
    Summer: ['Light','True','Soft'],
    Winter: ['Bright','True','Dark'],
    Autumn: ['Soft','True','Dark'],
    Spring: ['Light','True','Bright']
  };
  var labels = subLabels[ocaSeasonTab] || seasons.map(function(s){ return s.split(' ')[0]; });

  // Subcategory colours per vote button
  var subCols = ['#5588DD','#44AA66','#E07020'];

  var votes = ocaSeasonVotesSub[ocaSeasonTab] || {};
  var tally = {};
  labels.forEach(function(l){ tally[l] = 0; });
  Object.keys(votes).forEach(function(k){
    var v = votes[k];
    if (tally[v] !== undefined) tally[v]++;
  });

  var tallyHtml = '<div style="display:flex;gap:12px;align-items:center;padding:14px 20px;background:var(--warm);border-radius:12px;margin-bottom:20px;flex-wrap:wrap">'
    + '<div style="font-size:12px;font-weight:700;color:var(--charcoal);letter-spacing:.5px">TALLY</div>'
    + '<div style="display:flex;gap:16px;flex:1">'
    + labels.map(function(l,i){
        return '<div style="display:flex;align-items:center;gap:6px">'
          + '<div style="width:14px;height:14px;border-radius:3px;background:'+subCols[i]+'"></div>'
          + '<span style="font-size:13px;font-weight:700;color:'+subCols[i]+'">'+l.toUpperCase()+': '+tally[l]+'</span>'
          + '</div>';
      }).join('')
    + '</div>'
    + '<button class="btn btns" style="font-size:11px;padding:4px 12px" onclick="ocaSubClearVotes(\''+ocaSeasonTab+'\')">Clear All</button>'
    + '</div>';

  var numSwatches = OCA_SEASONS[seasons[0]].swatches.length;
  var face = ocaPhoto
    ? '<div style="position:absolute;inset:0;display:flex;align-items:flex-start;justify-content:center;overflow:hidden;pointer-events:none">'
      + '<img src="'+ocaPhoto+'" style="height:100%;object-fit:cover;object-position:center top">'
      + '</div>'
    : '';

  var cards = '';
  for (var i = 0; i < numSwatches; i++) {
    var vote = votes[i] || '';
    var swatchLabel = OCA_SEASONS[seasons[0]].swatches[i].name;

    var panels = seasons.map(function(sName, si) {
      var sw = OCA_SEASONS[sName] && OCA_SEASONS[sName].swatches[i];
      if (!sw) return '';
      var label = labels[si];
      var col   = subCols[si];
      var sel   = vote===label ? 'background:rgba(255,255,255,0.95);box-shadow:0 0 0 3px '+col : 'background:rgba(255,255,255,0.25)';
      var tick  = vote===label ? '&#10003;' : '';
      var safeGroup = ocaSeasonTab.replace(/'/g,"\\'");
      var safeLabel = label.replace(/'/g,"\\'");
      return '<div style="flex:1;position:relative;background:'+sw.hex+';overflow:hidden">'
        + face
        + '<div onclick="ocaSubVote(\''+safeGroup+'\','+i+',\''+safeLabel+'\')" '
        + 'style="position:absolute;top:14px;left:14px;width:38px;height:38px;border-radius:8px;border:2px solid rgba(255,255,255,0.8);'+sel+';cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:700;color:'+col+';z-index:10">'
        + tick + '</div>'
        + '<div style="position:absolute;bottom:10px;left:0;right:0;text-align:center;pointer-events:none">'
        + '<span style="font-size:13px;font-weight:800;color:white;letter-spacing:2px;text-shadow:0 1px 4px rgba(0,0,0,0.7)">'+label.toUpperCase()+'</span>'
        + '</div>'
        + '</div>';
    }).join(
      // thin gradient divider between panels
      '<div style="width:4px;flex-shrink:0"></div>'
    );

    cards += '<div style="margin-bottom:28px;border-radius:14px;overflow:hidden;box-shadow:0 4px 20px rgba(0,0,0,0.15)">'
      + '<div style="display:flex;width:100%;height:620px">'
      + panels
      + '</div>'
      + '<div style="background:#1a1a1a;padding:6px 20px;text-align:center">'
      + '<span style="font-size:12px;color:rgba(255,255,255,0.7);font-weight:500">'+swatchLabel+'</span>'
      + '</div>'
      + '</div>';
  }

  el.innerHTML = tallyHtml + cards;
}

// ── Render comparison tab ──
var ocaSeasonVotes = {};

function ocaSeasonVote(pairKey, idx, side) {
  if (!ocaSeasonVotes[pairKey]) ocaSeasonVotes[pairKey] = {};
  if (ocaSeasonVotes[pairKey][idx] === side) {
    delete ocaSeasonVotes[pairKey][idx];
  } else {
    ocaSeasonVotes[pairKey][idx] = side;
  }
  renderOca();
}

function ocaSeasonVotesClear(pairKey) {
  ocaSeasonVotes[pairKey] = {};
  renderOca();
}

function renderOcaComparison() {
  var allSeasonNames = Object.keys(OCA_SEASONS);

  function makeSelect(idx) {
    var opts = allSeasonNames.map(function(sn){
      return '<option value="'+sn+'" '+(ocaCompSeasons[idx]===sn?'selected':'')+'>'+sn+'</option>';
    }).join('');
    return '<select class="sm-inp" style="font-size:13px;padding:8px 12px;border-radius:8px;width:100%" onchange="ocaSetCompSeason('+idx+',this.value)">'
      + '<option value="">— Select Season —</option>'
      + opts + '</select>';
  }

  // Controls — 2 dropdowns only, no suggested pairs, no 3 seasons
  var controls = '<div style="background:white;border-radius:12px;border:1px solid var(--sand);padding:20px 24px;margin-bottom:20px">'
    + '<div style="font-size:13px;font-weight:600;color:var(--charcoal);margin-bottom:14px">Compare Seasons</div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">'
    + makeSelect(0) + makeSelect(1)
    + '</div></div>';

  var sNameA = ocaCompSeasons[0];
  var sNameB = ocaCompSeasons[1];

  if (!sNameA || !sNameB) {
    return controls + '<div style="text-align:center;padding:60px;color:var(--muted);font-size:13px">Select 2 seasons above to compare</div>';
  }

  var sA = OCA_SEASONS[sNameA];
  var sB = OCA_SEASONS[sNameB];
  if (!sA || !sB) {
    return controls + '<div style="text-align:center;padding:60px;color:var(--muted);font-size:13px">Season data not found</div>';
  }

  // Use simple numeric pairKey index to avoid string escaping issues in onclick
  var pairId = 'cmp_' + sNameA.replace(/\s/g,'_') + '__' + sNameB.replace(/\s/g,'_');

  var votes = ocaSeasonVotes[pairId] || {};
  var tally = {left:0, right:0, both:0};
  Object.keys(votes).forEach(function(k){
    if (votes[k]==='left') tally.left++;
    else if (votes[k]==='right') tally.right++;
    else if (votes[k]==='both') tally.both++;
  });

  var tallyBar = '<div style="display:flex;gap:12px;align-items:center;padding:12px 20px;background:var(--warm);border-radius:12px;margin-bottom:16px;flex-wrap:wrap">'
    + '<div style="font-size:12px;font-weight:700;color:var(--charcoal);letter-spacing:.5px">TALLY</div>'
    + '<div style="display:flex;gap:16px;flex:1">'
    + '<div style="font-size:13px;font-weight:700;color:#5588DD">'+sNameA+': '+tally.left+'</div>'
    + '<div style="font-size:13px;font-weight:700;color:#E07020">'+sNameB+': '+tally.right+'</div>'
    + '<div style="font-size:13px;font-weight:700;color:#888">BOTH: '+tally.both+'</div>'
    + '</div>'
    + '<button class="btn btns" style="font-size:11px;padding:4px 12px" onclick="ocaSeasonVotesClear(\''+pairId+'\')">Clear</button>'
    + '</div>';

  var len = Math.min(sA.swatches.length, sB.swatches.length);
  var cards = '';
  for (var j = 0; j < len; j++) {
    var swA = sA.swatches[j];
    var swB = sB.swatches[j];
    var vote = votes[j] || '';
    var leftSel  = vote==='left'  ? 'background:rgba(255,255,255,0.95);box-shadow:0 0 0 3px #5588DD' : 'background:rgba(255,255,255,0.25)';
    var rightSel = vote==='right' ? 'background:rgba(255,255,255,0.95);box-shadow:0 0 0 3px #E07020' : 'background:rgba(255,255,255,0.25)';
    var bothSel  = vote==='both'  ? 'background:rgba(255,255,255,0.95);box-shadow:0 0 0 3px #555'   : 'background:rgba(255,255,255,0.25)';
    var leftTick  = vote==='left'  ? '&#10003;' : '';
    var rightTick = vote==='right' ? '&#10003;' : '';
    var bothTick  = vote==='both'  ? '&#10003;' : '';

    var face = ocaPhoto
      ? '<div style="position:absolute;inset:0;display:flex;align-items:flex-start;justify-content:center;pointer-events:none">'
        + '<img src="'+ocaPhoto+'" style="height:100%;object-fit:cover;object-position:center top">'
        + '</div>'
      : '';

    cards += '<div style="margin-bottom:24px;border-radius:14px;overflow:hidden;box-shadow:0 4px 20px rgba(0,0,0,0.12)">'
      + '<div style="display:flex;width:100%;height:500px">'

      // Left — Season A
      + '<div style="flex:1;position:relative;background:'+swA.hex+';overflow:hidden">'
      + face
      + '<div onclick="ocaSeasonVote(\''+pairId+'\','+j+',\'left\')" style="position:absolute;top:14px;left:14px;width:38px;height:38px;border-radius:8px;border:2px solid rgba(255,255,255,0.8);'+leftSel+';cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:700;color:#5588DD;z-index:10">'+leftTick+'</div>'
      + '<div style="position:absolute;bottom:10px;left:0;right:0;text-align:center;pointer-events:none">'
      + '<div style="font-size:12px;font-weight:800;color:white;text-shadow:0 1px 4px rgba(0,0,0,0.7)">'+swA.name+'</div>'
      + '<div style="font-size:10px;color:rgba(255,255,255,0.75)">'+sNameA+'</div>'
      + '</div></div>'

      // BOTH strip
      + '<div style="position:relative;width:52px;flex-shrink:0;background:linear-gradient(to right,'+swA.hex+','+swB.hex+')">'
      + '<div onclick="ocaSeasonVote(\''+pairId+'\','+j+',\'both\')" style="position:absolute;top:14px;left:50%;transform:translateX(-50%);width:38px;height:38px;border-radius:8px;border:2px solid rgba(255,255,255,0.8);'+bothSel+';cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:700;color:#555;z-index:10">'+bothTick+'</div>'
      + '<div style="position:absolute;bottom:10px;left:50%;transform:translateX(-50%);white-space:nowrap;pointer-events:none"><span style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.8);text-shadow:0 1px 3px rgba(0,0,0,0.8)">BOTH</span></div>'
      + '</div>'

      // Right — Season B
      + '<div style="flex:1;position:relative;background:'+swB.hex+';overflow:hidden">'
      + face
      + '<div onclick="ocaSeasonVote(\''+pairId+'\','+j+',\'right\')" style="position:absolute;top:14px;right:14px;width:38px;height:38px;border-radius:8px;border:2px solid rgba(255,255,255,0.8);'+rightSel+';cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:700;color:#E07020;z-index:10">'+rightTick+'</div>'
      + '<div style="position:absolute;bottom:10px;left:0;right:0;text-align:center;pointer-events:none">'
      + '<div style="font-size:12px;font-weight:800;color:white;text-shadow:0 1px 4px rgba(0,0,0,0.7)">'+swB.name+'</div>'
      + '<div style="font-size:10px;color:rgba(255,255,255,0.75)">'+sNameB+'</div>'
      + '</div></div>'

      + '</div></div>';
  }

  return controls + tallyBar + cards;
}

function ocaSetCompSeason(idx, val) {
  ocaCompSeasons[idx] = val;
  renderOca();
}

function ocaSetPanels(n) {
  if (n===2) ocaCompSeasons[2]='';
  if (n===3 && !ocaCompSeasons[2]) ocaCompSeasons[2]='';
  // force 3 panel mode by setting empty string vs undefined
  if (n===3) ocaCompSeasons = [ocaCompSeasons[0]||'', ocaCompSeasons[1]||'', ocaCompSeasons[2]!==undefined?ocaCompSeasons[2]:''];
  if (n===2) ocaCompSeasons = [ocaCompSeasons[0]||'', ocaCompSeasons[1]||''];
  renderOca();
}

function ocaLoadPair(seasons) {
  ocaCompSeasons = [seasons[0], seasons[1]];
  ocaTab = 'compare';
  document.querySelectorAll('[id^="oca-tab-"]').forEach(function(b){ b.classList.remove('on'); });
  var tb = document.getElementById('oca-tab-compare'); if(tb) tb.classList.add('on');
  renderOca();
}

// ── Master render ──
function renderOca() {
  var content = document.getElementById('oca-content'); if(!content) return;

  // update photo upload area
  var prev = document.getElementById('oca-photo-preview');
  var plac = document.getElementById('oca-photo-placeholder');
  if(prev && plac) {
    if(ocaPhoto){ prev.src=ocaPhoto; prev.style.display='block'; plac.style.display='none'; }
    else { prev.style.display='none'; plac.style.display='flex'; }
  }

  if (ocaTab==='draping') {
    content.innerHTML = renderOcaDraping();
  } else if (ocaTab==='seasons') {
    content.innerHTML = '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px" id="oca-season-tabs">'
      + ['Summer','Winter','Autumn','Spring'].map(function(g){
          return '<button id="oca-stab-'+g+'" class="vt-tab'+(g===ocaSeasonTab?' on':'')+'" onclick="setOcaSeasonTab(\''+g+'\')">'+g+'</button>';
        }).join('')
      + '</div>'
      + '<div id="oca-seasons-content"></div>';
    renderOcaSeasons();
  } else if (ocaTab==='compare') {
    try {
      content.innerHTML = renderOcaComparison();
    } catch(err) {
      content.innerHTML = '<div style="padding:40px;color:red;font-size:13px;font-family:monospace">COMPARE ERROR: ' + err.message + '<br><br>' + (err.stack||'').replace(/\n/g,'<br>') + '</div>';
    }
  } else if (ocaTab==='fundamentals') {
    content.innerHTML = renderOcaFundamentals();
    setTimeout(function(){ ocaUpdateContrast(); }, 80);
  } else if (ocaTab==='metals') {
    content.innerHTML = renderOcaMetals();
  } else if (ocaTab==='blush') {
    content.innerHTML = renderOcaBlush();
    setTimeout(setupBlushDrag, 80);
  } else if (ocaTab==='coolwarm') {
    content.innerHTML = renderOcaCoolWarm();
  }
}



