var ocaFundSliders = {skin:5, hair:3, eyes:7};
var ocaFundSliderPos = {skin:{x:0,y:0}, hair:{x:0,y:40}, eyes:{x:0,y:80}};
var ocaDragState = null;

// Value scale state — scaleX is the drag offset (negative = scrolled right = higher values visible)
var ocaScaleX = 0;
var ocaScaleDragging = false;

// 10 greyscale values: index 0 = value 1 (darkest) → index 9 = value 10 (lightest)
var GREY_VALS = [
  {n:1,  bg:'#111111'}, {n:2,  bg:'#222222'}, {n:3,  bg:'#383838'},
  {n:4,  bg:'#505050'}, {n:5,  bg:'#686868'}, {n:6,  bg:'#848484'},
  {n:7,  bg:'#9E9E9E'}, {n:8,  bg:'#B8B8B8'}, {n:9,  bg:'#D0D0D0'},
  {n:10, bg:'#E8E8E8'}
];

// Draggable feature tags (skin, hair, eyes) — each stores which scale value it's matched to
var ocaFundTags = {
  skin: {val:5, x:20,  y:60,  col:'#E05555', label:'SKIN'},
  hair: {val:3, x:20,  y:160, col:'#5588DD', label:'HAIR'},
  eyes: {val:7, x:20,  y:260, col:'#44AA66', label:'EYES'}
};

function scaleStartDrag(e) {
  e.preventDefault();
  var startX = e.clientX - ocaScaleX;
  var panel  = document.getElementById('oca-scale-strip');
  var win    = document.getElementById('oca-scale-window');
  if (!panel || !win) return;
  var colW   = win.offsetWidth; // window shows exactly 1 column
  var minX   = -(9 * colW);    // can scroll to show column 10
  var maxX   = 0;               // leftmost = column 1
  function onMove(ev) {
    ocaScaleX = Math.max(minX, Math.min(maxX, ev.clientX - startX));
    panel.style.transform = 'translateX(' + ocaScaleX + 'px)';
    // Work out which column is centred in window
    var idx = Math.round(-ocaScaleX / colW);
    idx = Math.max(0, Math.min(9, idx));
    var lbl = document.getElementById('oca-scale-label');
    if (lbl) lbl.textContent = 'Value ' + GREY_VALS[idx].n;
  }
  function onUp() {
    // Snap to nearest column
    var colW2 = win.offsetWidth;
    var idx = Math.round(-ocaScaleX / colW2);
    idx = Math.max(0, Math.min(9, idx));
    ocaScaleX = -(idx * colW2);
    panel.style.transform = 'translateX(' + ocaScaleX + 'px)';
    panel.style.transition = 'transform .2s ease';
    setTimeout(function(){ panel.style.transition = ''; }, 220);
    document.removeEventListener('mousemove', onMove);
    document.removeEventListener('mouseup', onUp);
  }
  panel.style.transition = 'none';
  document.addEventListener('mousemove', onMove);
  document.addEventListener('mouseup', onUp);
}

function scaleTouchDrag(e) {
  var t = e.touches[0];
  var startX = t.clientX - ocaScaleX;
  var panel  = document.getElementById('oca-scale-strip');
  var win    = document.getElementById('oca-scale-window');
  if (!panel || !win) return;
  var colW = win.offsetWidth;
  var minX = -(9 * colW);
  function onMove(ev) {
    ev.preventDefault();
    var tc = ev.touches[0];
    ocaScaleX = Math.max(minX, Math.min(0, tc.clientX - startX));
    panel.style.transform = 'translateX(' + ocaScaleX + 'px)';
    var idx = Math.round(-ocaScaleX / colW);
    idx = Math.max(0, Math.min(9, idx));
    var lbl = document.getElementById('oca-scale-label');
    if (lbl) lbl.textContent = 'Value ' + GREY_VALS[idx].n;
  }
  function onEnd() {
    var colW2 = win.offsetWidth;
    var idx = Math.round(-ocaScaleX / colW2);
    idx = Math.max(0, Math.min(9, idx));
    ocaScaleX = -(idx * colW2);
    panel.style.transform = 'translateX(' + ocaScaleX + 'px)';
    panel.style.transition = 'transform .2s ease';
    setTimeout(function(){ panel.style.transition = ''; }, 220);
    document.removeEventListener('touchmove', onMove);
    document.removeEventListener('touchend', onEnd);
  }
  panel.style.transition = 'none';
  document.addEventListener('touchmove', onMove, {passive:false});
  document.addEventListener('touchend', onEnd);
}

function tagDragStart(e, key) {
  e.preventDefault();
  e.stopPropagation();
  var el = document.getElementById('oca-tag-' + key);
  var container = document.getElementById('oca-fund-preview');
  if (!el || !container) return;
  var t = ocaFundTags[key];
  var startX = e.clientX - t.x;
  var startY = e.clientY - t.y;
  function onMove(ev) {
    t.x = ev.clientX - startX;
    t.y = ev.clientY - startY;
    el.style.left = t.x + 'px';
    el.style.top  = t.y + 'px';
  }
  function onUp() {
    document.removeEventListener('mousemove', onMove);
    document.removeEventListener('mouseup', onUp);
  }
  document.addEventListener('mousemove', onMove);
  document.addEventListener('mouseup', onUp);
}

function tagTouchStart(e, key) {
  e.preventDefault();
  var tc = e.touches[0];
  var el = document.getElementById('oca-tag-' + key);
  if (!el) return;
  var t = ocaFundTags[key];
  var startX = tc.clientX - t.x;
  var startY = tc.clientY - t.y;
  function onMove(ev) {
    ev.preventDefault();
    var tc2 = ev.touches[0];
    t.x = tc2.clientX - startX;
    t.y = tc2.clientY - startY;
    el.style.left = t.x + 'px';
    el.style.top  = t.y + 'px';
  }
  function onEnd() {
    document.removeEventListener('touchmove', onMove);
    document.removeEventListener('touchend', onEnd);
  }
  document.addEventListener('touchmove', onMove, {passive:false});
  document.addEventListener('touchend', onEnd);
}

function renderOcaFundamentals() {
  var photoHtml = ocaPhoto
    ? '<img src="'+ocaPhoto+'" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center top;filter:grayscale(100%);display:block;">'
    : '<div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--muted);gap:8px;border:2px dashed var(--sand);border-radius:8px"><div style=\'font-size:32px\'>&#128247;</div><div style=\'font-size:13px\'>Upload a photo above</div></div>';

  // Tags: horizontal — label text on left, greyscale swatch extends right, open notch cut from right end
  var tags = Object.keys(ocaFundTags).map(function(key) {
    var t = ocaFundTags[key];
    var greyBg = GREY_VALS[t.val - 1].bg;
    var numCol = t.val > 6 ? '#333333' : '#ffffff';
    // Swatch: 80px wide × 36px tall, notch cut from right side centre
    // polygon: TL→ top-notch-start → notch-top-right → notch-bottom-right → bottom-notch-start → BL
    // notch is 28px tall (centred), 20px deep from right
    var clip = 'polygon(0% 0%, 100% 0%, 100% 20%, 75% 20%, 75% 80%, 100% 80%, 100% 100%, 0% 100%)';

    return '<div id="oca-tag-' + key + '" '
      + 'style="position:absolute;left:' + t.x + 'px;top:' + t.y + 'px;'
      + 'z-index:10;cursor:move;user-select:none;touch-action:none;'
      + 'display:flex;align-items:center;gap:5px;filter:drop-shadow(0 2px 6px rgba(0,0,0,0.35))" '
      + 'onmousedown="tagDragStart(event,\'' + key + '\')" '
      + 'ontouchstart="tagTouchStart(event,\'' + key + '\')">'

      // Floating label to the left
      + '<span style="font-size:8px;font-weight:800;color:' + t.col + ';'
      + 'letter-spacing:1.5px;text-transform:uppercase;'
      + 'text-shadow:0 1px 3px rgba(0,0,0,0.6);white-space:nowrap;flex-shrink:0">'
      + t.label + '</span>'

      // Horizontal greyscale swatch with notch cut from right
      + '<div id="oca-tag-swatch-' + key + '" '
      + 'style="position:relative;width:80px;height:36px;border-radius:6px 0 0 6px;'
      + 'background:' + greyBg + ';clip-path:' + clip + ';">'
      + '<div id="oca-tag-num-' + key + '" '
      + 'style="position:absolute;top:50%;left:35%;transform:translate(-50%,-50%);'
      + 'font-size:10px;font-weight:800;color:' + numCol + ';pointer-events:none">' + t.val + '</div>'
      + '</div>'
      + '</div>';
  }).join('');

  // Sidebar controls
  var tagControls = Object.keys(ocaFundTags).map(function(key) {
    var t = ocaFundTags[key];
    var greyBg = GREY_VALS[t.val - 1].bg;
    return '<div style="background:white;border:1px solid var(--sand);border-radius:10px;padding:14px 16px;margin-bottom:10px">'
      + '<div style="display:flex;align-items:center;gap:10px;margin-bottom:10px">'
      + '<div style="width:14px;height:14px;border-radius:50%;background:' + t.col + ';flex-shrink:0"></div>'
      + '<div style="font-size:12px;font-weight:600;color:var(--deep)">' + t.label + '</div>'
      + '<div id="oca-ctrl-swatch-' + key + '" style="margin-left:auto;width:32px;height:20px;border-radius:4px;background:' + greyBg + ';border:1px solid var(--sand)"></div>'
      + '<div id="oca-ctrl-num-' + key + '" style="font-size:12px;font-weight:700;color:var(--deep);min-width:16px;text-align:right">' + t.val + '</div>'
      + '</div>'
      + '<input type="range" min="1" max="10" value="' + t.val + '" '
      + 'style="width:100%;accent-color:' + t.col + ';cursor:pointer" '
      + 'oninput="ocaTagVal(\'' + key + '\',this.value)">'
      + '<div style="display:flex;justify-content:space-between;margin-top:3px">'
      + '<span style="font-size:9px;color:var(--muted)">Dark 1</span>'
      + '<span style="font-size:9px;color:var(--muted)">Light 10</span>'
      + '</div>'
      + '</div>';
  }).join('');

  return '<div>'

    // 1. COLOUR SAMPLING — top
    + '<div style="font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--muted);margin-bottom:14px">Colour Sampling</div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:32px">'
    + '<div class="card"><div class="ch"><div class="ct">Sample from Photo</div>'
    + '<div style="font-size:11px;color:var(--muted)">Select a slot on the right, then click the photo to sample.</div></div>'
    + '<div class="cb">'
    + '<div id="oca-sample-photo" style="position:relative;width:100%;padding-top:115%;border-radius:8px;overflow:hidden;background:var(--sand);cursor:crosshair" onclick="ocaSampleClick(event)">'
    + (ocaPhoto ? '<img src="'+ocaPhoto+'" id="oca-sample-img" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center top;display:block;pointer-events:none">' : '<div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--muted);gap:8px"><div style=\'font-size:32px\'>&#128247;</div><div style=\'font-size:13px\'>Upload a photo above</div></div>')
    + '<div id="oca-sample-cursor" style="display:none;position:absolute;width:16px;height:16px;border-radius:50%;border:2px solid white;box-shadow:0 0 0 1px rgba(0,0,0,0.5);transform:translate(-50%,-50%);pointer-events:none;z-index:10"></div>'
    + '</div></div></div>'
    + '<div><div style="font-size:11px;color:var(--muted);margin-bottom:12px">Click a slot to select it, then click the photo or use the colour picker.</div>'
    + ocaSampleSwatchPanel()
    + '</div></div>'

    // 2. CONTRAST
    + '<div style="font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--muted);margin-bottom:14px">Contrast</div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:32px">'
    + '<div class="card"><div class="ch"><div class="ct">Contrast</div>'
    + '<div style="font-size:11px;color:var(--muted)">Drag each tag over the matching feature.</div></div>'
    + '<div class="cb">'
    + '<div id="oca-fund-preview" style="position:relative;width:100%;padding-top:115%;border-radius:8px;overflow:hidden;background:var(--sand)">'
    + photoHtml + tags
    + '</div></div></div>'
    + '<div>'
    + '<div style="font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--muted);margin-bottom:10px">Feature Values</div>'
    + tagControls
    + '<div style="background:var(--warm);border-radius:10px;padding:10px 14px;border:1px solid var(--sand)">'
    + '<div style="font-size:11px;font-weight:600;color:var(--deep);margin-bottom:6px">Contrast Range</div>'
    + '<div id="oca-contrast-result" style="font-size:12px;color:var(--brown);line-height:1.5"></div>'
    + '</div></div>'
    + '</div>'

    // 3. SKIN TONE
    + '<div style="font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--muted);margin-bottom:14px">Skin Tone</div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:24px">'
    + '<div class="card"><div class="ch"><div class="ct">Undertone Draping</div>'
    + '<div style="font-size:11px;color:var(--muted)">Drag a strip over the face to match undertone.</div></div>'
    + '<div class="cb"><div id="oca-tone-preview" style="position:relative;width:100%;padding-top:115%;border-radius:8px;overflow:hidden;background:var(--sand)">'
    + (ocaPhoto ? '<img src="'+ocaPhoto+'" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center top;display:block;">' : '<div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--muted);gap:8px"><div style=\'font-size:32px\'>&#128247;</div><div style=\'font-size:13px\'>Upload a photo above</div></div>')
    + ocaToneStripEls()
    + '</div></div></div>'
    + '<div><div style="font-size:11px;color:var(--muted);margin-bottom:12px">Click to add to photo, drag to reposition.</div>'
    + ocaTonePalette()
    + '</div></div>'

    + '</div>';
}

