var LIP_OPTIONS = [
  {key:'cool_lip',     name:'Bright Red', img:'data:image/png;base64,'},
  {key:'warm_lip',     name:'Warm Peach', img:'data:image/png;base64,'},
  {key:'red_cool_lip', name:'Cool Red',   img:'data:image/png;base64,'},
  {key:'red_brown_lip',name:'Red Brown',  img:'data:image/png;base64,'}
,
  {key:'coral_lip',     name:'Bright Coral',       img:'data:image/png;base64,'},
  {key:'pink_lip',      name:'Hot Pink',         img:'data:image/png;base64,'},
  {key:'nude_lip',      name:'Nude',         img:'data:image/png;base64,'},
  {key:'berry_pink_lip',name:'Berry Pink',   img:'data:image/png;base64,'},
  {key:'deep_red_lip',  name:'Deep Red',     img:'data:image/png;base64,'}];
var ocaLipState = {
  cool_lip:     {x:10, y:10, w:200, opacity:0.9, active:false},
  warm_lip:     {x:10, y:10, w:200, opacity:0.9, active:false},
  red_cool_lip: {x:10, y:10, w:200, opacity:0.9, active:false},
  red_brown_lip:{x:10, y:10, w:200, opacity:0.9, active:false},
  coral_lip:    {x:10, y:10, w:200, opacity:0.9, active:false},
  pink_lip:     {x:10, y:10, w:200, opacity:0.9, active:false},
  nude_lip:     {x:10, y:10, w:200, opacity:0.9, active:false},
  berry_pink_lip:{x:10, y:10, w:200, opacity:0.9, active:false},
  deep_red_lip: {x:10, y:10, w:200, opacity:0.9, active:false}
};
var ocaLipState2 = {
  cool_lip:     {x:10, y:10},
  warm_lip:     {x:10, y:10},
  red_cool_lip: {x:10, y:10},
  red_brown_lip:{x:10, y:10},
  coral_lip:    {x:10, y:10},
  pink_lip:     {x:10, y:10},
  nude_lip:     {x:10, y:10},
  berry_pink_lip:{x:10, y:10},
  deep_red_lip: {x:10, y:10}
};
function lipGetStyle(key) {
  var s = ocaLipState[key];
  return 'position:absolute;left:'+s.x+'px;top:'+s.y+'px;width:'+s.w+'px;height:auto;opacity:'+s.opacity+';z-index:5;cursor:move;user-select:none;touch-action:none;';
}
function lipUpdateEl(key) {
  var s = ocaLipState[key];
  var s2 = ocaLipState2[key];
  var style1 = lipGetStyle(key);
  var style2 = 'position:absolute;left:'+s2.x+'px;top:'+s2.y+'px;width:'+s.w+'px;height:auto;opacity:'+s.opacity+';z-index:5;cursor:move;user-select:none;touch-action:none;';
  var el1 = document.getElementById('lip-drape-'+key);
  var el2 = document.getElementById('lip-drape2-'+key);
  if (el1) el1.setAttribute('style', style1);
  if (el2) el2.setAttribute('style', style2);
}
function lipDragStart(e, key) {
  e.preventDefault();
  var el = document.getElementById('lip-drape-'+key);
  if (!el) return;
  var s = ocaLipState[key];
  var ox = e.clientX - s.x, oy = e.clientY - s.y;
  function onMove(ev) { s.x=ev.clientX-ox; s.y=ev.clientY-oy; el.style.left=s.x+'px'; el.style.top=s.y+'px'; }
  function onUp() { document.removeEventListener('mousemove',onMove); document.removeEventListener('mouseup',onUp); }
  document.addEventListener('mousemove', onMove);
  document.addEventListener('mouseup', onUp);
}
function lipTouchStart(e, key) {
  e.preventDefault();
  var tc = e.touches[0], el = document.getElementById('lip-drape-'+key);
  if (!el) return;
  var s = ocaLipState[key];
  var ox = tc.clientX-s.x, oy = tc.clientY-s.y;
  function onMove(ev) { ev.preventDefault(); var t=ev.touches[0]; s.x=t.clientX-ox; s.y=t.clientY-oy; el.style.left=s.x+'px'; el.style.top=s.y+'px'; }
  function onEnd() { document.removeEventListener('touchmove',onMove); document.removeEventListener('touchend',onEnd); }
  document.addEventListener('touchmove', onMove, {passive:false});
  document.addEventListener('touchend', onEnd);
}
function lipDragStart2(e, key) {
  e.preventDefault();
  var el = document.getElementById('lip-drape2-'+key);
  if (!el) return;
  var s = ocaLipState2[key];
  var ox = e.clientX - s.x, oy = e.clientY - s.y;
  function onMove(ev) { s.x=ev.clientX-ox; s.y=ev.clientY-oy; el.style.left=s.x+'px'; el.style.top=s.y+'px'; }
  function onUp() { document.removeEventListener('mousemove',onMove); document.removeEventListener('mouseup',onUp); }
  document.addEventListener('mousemove', onMove);
  document.addEventListener('mouseup', onUp);
}
function lipTouchStart2(e, key) {
  e.preventDefault();
  var tc = e.touches[0], el = document.getElementById('lip-drape2-'+key);
  if (!el) return;
  var s = ocaLipState2[key];
  var ox = tc.clientX-s.x, oy = tc.clientY-s.y;
  function onMove(ev) { ev.preventDefault(); var t=ev.touches[0]; s.x=t.clientX-ox; s.y=t.clientY-oy; el.style.left=s.x+'px'; el.style.top=s.y+'px'; }
  function onEnd() { document.removeEventListener('touchmove',onMove); document.removeEventListener('touchend',onEnd); }
  document.addEventListener('touchmove', onMove, {passive:false});
  document.addEventListener('touchend', onEnd);
}
function lipToggle(key) {
  ocaLipState[key].active = !ocaLipState[key].active;
  renderOca();
}
function lipControl(key, prop, val) {
  ocaLipState[key][prop] = parseFloat(val);
  lipUpdateEl(key);
}
function lipSlider(key, prop, label, unit, min, max, val, step) {
  var id = 'lsl-'+key+'-'+prop;
  var lid = 'lbl-'+key+'-'+prop;
  var disp = unit==='px' ? Math.round(val)+'px' : parseFloat(val).toFixed(2);
  var upd = unit==='px' ? "Math.round(this.value)+'px'" : "parseFloat(this.value).toFixed(2)";
  var esc_key = key.replace(/'/g,"\\'");
  var esc_lid = lid.replace(/'/g,"\\'");
  return '<div>'
    +'<div style="display:flex;justify-content:space-between;margin-bottom:5px">'
    +'<label style="font-size:11px;color:var(--muted)">'+label+'</label>'
    +'<span id="'+lid+'" style="font-size:11px;font-weight:600;color:var(--deep)">'+disp+'</span>'
    +'</div>'
    +'<input id="'+id+'" type="range" min="'+min+'" max="'+max+'" step="'+step+'" value="'+val+'"'
    +' style="width:100%;accent-color:var(--accent);cursor:pointer"'
    +' oninput="lipControl(\''+esc_key+'\',\''+prop+'\',this.value);document.getElementById(\''+esc_lid+'\').textContent='+upd+'">'
    +'</div>';
}
function renderLipControls() {
  return LIP_OPTIONS.map(function(d) {
    var s = ocaLipState[d.key];
    var active = s.active;
    var out = '<div style="background:white;border:1px solid var(--sand);border-radius:10px;padding:12px 14px;margin-bottom:10px">'
      +'<div style="display:flex;align-items:center;gap:10px'+(active?';margin-bottom:12px':'')+'">'
      +'<div style="width:44px;height:30px;border-radius:6px;overflow:hidden;background:var(--sand);flex-shrink:0">'
      +'<img src="'+d.img+'" style="width:100%;height:100%;object-fit:contain"></div>'
      +'<div style="flex:1;font-size:12px;font-weight:600;color:var(--deep)">'+d.name+'</div>'
      +'<button onclick="lipToggle(\''+d.key+'\')" style="font-size:10px;font-weight:700;letter-spacing:1px;padding:5px 12px;border-radius:20px;cursor:pointer;border:none;'
      +(active?'background:var(--accent);color:white':'background:var(--sand);color:var(--muted)')+'">'
      +(active?'ON':'ADD')+'</button></div>';
    if (active) {
      out += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">'
        +lipSlider(d.key,'w','Size','px',80,360,s.w,1)
        +lipSlider(d.key,'opacity','Opacity','',0.1,1.0,s.opacity,0.01)
        +'</div>';
    }
    out += '</div>';
    return out;
  }).join('');
}

// ══════════════════════════════════════════════════
// COOL VS WARM TAB
// ══════════════════════════════════════════════════
var ocaCwMode = 'dark';

var ocaCwVotes = {dark:{}, light:{}};

function ocaCwVote(mode, idx, side) {
  if (!ocaCwVotes[mode]) ocaCwVotes[mode] = {};
  if (ocaCwVotes[mode][idx] === side) {
    delete ocaCwVotes[mode][idx];
  } else {
    ocaCwVotes[mode][idx] = side;
  }
  renderOca();
}

function ocaCwClearVotes() {
  ocaCwVotes[ocaCwMode] = {};
  renderOca();
}

function renderOcaCoolWarm() {
  var pairs = OCA_CW[ocaCwMode];
  var darkOn  = ocaCwMode==='dark'  ? ' on' : '';
  var lightOn = ocaCwMode==='light' ? ' on' : '';
  var tally   = {cool:0, warm:0, both:0};
  pairs.forEach(function(p,i){
    var v = ocaCwVotes[ocaCwMode] && ocaCwVotes[ocaCwMode][i];
    if(v==='cool') tally.cool++;
    else if(v==='warm') tally.warm++;
    else if(v==='both') tally.both++;
  });

  var tallyHtml = '<div style="display:flex;gap:12px;align-items:center;padding:14px 20px;background:var(--warm);border-radius:12px;margin-bottom:20px;flex-wrap:wrap">'
    + '<div style="font-size:12px;font-weight:700;color:var(--charcoal);letter-spacing:.5px">TALLY</div>'
    + '<div style="display:flex;gap:16px;flex:1">'
    + '<div style="display:flex;align-items:center;gap:6px"><div style="width:14px;height:14px;border-radius:3px;background:#5588DD"></div><span style="font-size:13px;font-weight:700;color:#5588DD">COOL: ' + tally.cool + '</span></div>'
    + '<div style="display:flex;align-items:center;gap:6px"><div style="width:14px;height:14px;border-radius:3px;background:#E07020"></div><span style="font-size:13px;font-weight:700;color:#E07020">WARM: ' + tally.warm + '</span></div>'
    + '<div style="display:flex;align-items:center;gap:6px"><div style="width:14px;height:14px;border-radius:3px;background:#888"></div><span style="font-size:13px;font-weight:700;color:#888">BOTH: ' + tally.both + '</span></div>'
    + '</div>'
    + '<button class="btn btns" style="font-size:11px;padding:4px 12px" onclick="ocaCwClearVotes()">Clear All</button>'
    + '</div>';

  var cards = pairs.map(function(p, i) {
    var vote    = (ocaCwVotes[ocaCwMode] && ocaCwVotes[ocaCwMode][i]) || '';
    var coolSel = vote==='cool' ? 'background:rgba(255,255,255,0.95);box-shadow:0 0 0 3px #5588DD' : 'background:rgba(255,255,255,0.25)';
    var warmSel = vote==='warm' ? 'background:rgba(255,255,255,0.95);box-shadow:0 0 0 3px #E07020' : 'background:rgba(255,255,255,0.25)';
    var bothSel = vote==='both' ? 'background:rgba(255,255,255,0.95);box-shadow:0 0 0 3px #555'   : 'background:rgba(255,255,255,0.25)';
    var coolTick = vote==='cool' ? '&#10003;' : '';
    var warmTick = vote==='warm' ? '&#10003;' : '';
    var bothTick = vote==='both' ? '&#10003;' : '';

    var face = ocaPhoto
      ? '<div style="position:absolute;inset:0;display:flex;align-items:flex-start;justify-content:center;overflow:hidden;pointer-events:none">'
        + '<img src="' + ocaPhoto + '" style="height:100%;object-fit:cover;object-position:center top">'
        + '</div>'
      : '';

    return '<div style="margin-bottom:28px;border-radius:14px;overflow:hidden;box-shadow:0 4px 20px rgba(0,0,0,0.15)">'
      + '<div style="display:flex;width:100%;height:620px">'

      // COOL half
      + '<div style="flex:1;position:relative;background:' + p.cool + ';overflow:hidden">'
      + face
      + '<div onclick="ocaCwVote(\'' + ocaCwMode + '\',' + i + ',\'cool\')" '
      + 'style="position:absolute;top:14px;left:14px;width:38px;height:38px;border-radius:8px;border:2px solid rgba(255,255,255,0.8);' + coolSel + ';cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:700;color:#5588DD;z-index:10">'
      + coolTick + '</div>'
      + '<div style="position:absolute;bottom:10px;left:0;right:0;text-align:center;pointer-events:none">'
      + '<span style="font-size:13px;font-weight:800;color:white;letter-spacing:2px;text-shadow:0 1px 4px rgba(0,0,0,0.7)">COOL</span>'
      + '</div>'
      + '</div>'

      // BOTH strip
      + '<div style="position:relative;width:52px;flex-shrink:0;background:linear-gradient(to right,' + p.cool + ',' + p.warm + ')">'
      + '<div onclick="ocaCwVote(\'' + ocaCwMode + '\',' + i + ',\'both\')" '
      + 'style="position:absolute;top:14px;left:50%;transform:translateX(-50%);width:38px;height:38px;border-radius:8px;border:2px solid rgba(255,255,255,0.8);' + bothSel + ';cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:700;color:#555;z-index:10">'
      + bothTick + '</div>'
      + '<div style="position:absolute;bottom:10px;left:50%;transform:translateX(-50%);white-space:nowrap;pointer-events:none">'
      + '<span style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.8);letter-spacing:1px;text-shadow:0 1px 3px rgba(0,0,0,0.8)">BOTH</span>'
      + '</div>'
      + '</div>'

      // WARM half
      + '<div style="flex:1;position:relative;background:' + p.warm + ';overflow:hidden">'
      + face
      + '<div onclick="ocaCwVote(\'' + ocaCwMode + '\',' + i + ',\'warm\')" '
      + 'style="position:absolute;top:14px;right:14px;width:38px;height:38px;border-radius:8px;border:2px solid rgba(255,255,255,0.8);' + warmSel + ';cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:700;color:#E07020;z-index:10">'
      + warmTick + '</div>'
      + '<div style="position:absolute;bottom:10px;left:0;right:0;text-align:center;pointer-events:none">'
      + '<span style="font-size:13px;font-weight:800;color:white;letter-spacing:2px;text-shadow:0 1px 4px rgba(0,0,0,0.7)">WARM</span>'
      + '</div>'
      + '</div>'

      + '</div>'
      // label — just the pair name, no bottom bar styling
      + '<div style="background:#1a1a1a;padding:6px 20px;text-align:center">'
      + '<span style="font-size:12px;color:rgba(255,255,255,0.7);font-weight:500">' + p.label + '</span>'
      + '</div>'
      + '</div>';
  }).join('');

  return '<div>'
    + '<div style="display:flex;gap:8px;margin-bottom:16px">'
    + '<button id="oca-cw-dark"  class="vt-tab' + darkOn  + '" onclick="ocaSetCwMode(\'dark\')">Med / Dark Features</button>'
    + '<button id="oca-cw-light" class="vt-tab' + lightOn + '" onclick="ocaSetCwMode(\'light\')">Lighter Features</button>'
    + '</div>'
    + tallyHtml
    + cards
    + '</div>';
}

function ocaSetCwMode(mode) {
  ocaCwMode = mode;
  renderOca();
}


function launchApp() {
  var u = USERS[curUser];
  var ls = document.getElementById('login-screen');
  ls.classList.add('hide');
  setTimeout(function(){ ls.style.display='none'; }, 500);
  document.getElementById('app').style.display = 'flex';
  document.getElementById('uname-display').textContent = u.name + ' · ' + u.role;
  var d = new Date();
  var h = d.getHours();
  if (curUser === 'latisha') {
    document.getElementById('dash-date').textContent = d.toLocaleDateString('en-AU',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
    document.getElementById('dash-greet').textContent = 'Good ' + (h<12?'morning':h<17?'afternoon':'evening') + ', ' + u.name;
  }
  buildNav(u.pages);
  // Show a subtle loading indicator while cloud data loads
  var loadingBanner = document.createElement('div');
  loadingBanner.id = 'yszn-loading-banner';
  loadingBanner.style.cssText = 'position:fixed;top:0;left:220px;right:0;background:#F7F3EE;border-bottom:1px solid #E5DDD4;padding:10px 24px;font-size:12px;color:#8A7D72;letter-spacing:1px;text-transform:uppercase;z-index:999;text-align:center';
  loadingBanner.textContent = 'Loading your data...';
  document.body.appendChild(loadingBanner);

  loadData(); // async — _applyLoadedData fires when ready

  // Render initial UI with default/empty state immediately
  updateTaskBadge();
  commsNavBadge();
  showPage(u.pages[0]);
  renderClients();
  renderSops();
  renderAudit();
  renderBrands();
  renderWatchlist();
  renderTaskBoard();
  renderToursPage();
  renderSocialPage();
  renderAdCreativePage();
  renderGoals();
  renderFinances();
  if (curUser === 'latisha') {
    renderStaffPage();
    renderDashTaskProgress();
  } else {
    renderMyHub();
  }
  // Remove loading banner after a short delay (data will have loaded by then)
  setTimeout(function() {
    var b = document.getElementById('yszn-loading-banner');
    if (b) b.remove();
  }, 3000);
}

function buildNav(allowed) {
  var nav = document.getElementById('snav');
  nav.innerHTML = '';
  var lastSec = null;
  NAV.forEach(function(item) {
    if (allowed.indexOf(item.id) === -1) return;
    if (item.sec && item.sec !== lastSec) {
      var lbl = document.createElement('div');
      lbl.className = 'nsec'; lbl.textContent = item.sec;
      nav.appendChild(lbl); lastSec = item.sec;
    }
    var btn = document.createElement('div');
    btn.className = 'nitem'; btn.id = 'n-'+item.id;
    btn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">'+item.icon+'</svg>'+item.lbl;
    if (item.id==='comms') {
      var bdg = document.createElement('span');
      bdg.id = 'n-comms-badge';
      bdg.style.cssText = 'display:none;background:var(--deep);color:#F9F5F0;border-radius:10px;padding:1px 7px;font-size:10px;font-weight:700;margin-left:auto;min-width:18px;text-align:center;';
      bdg.textContent = '0';
      btn.appendChild(bdg);
    }
    btn.onclick = (function(id){ return function(){ showPage(id); }; })(item.id);
    nav.appendChild(btn);
  });
}
function showPage(id) {
  if (id==='vietnam') renderVietnamTour();
  if (id==='sops') { renderSops(); renderPasswords(); }
  if (id==='vouchers') renderVoucherTab();
  if (id==='online') { renderOca(); if (typeof mpPreWarm === 'function') mpPreWarm(); }
  document.querySelectorAll('.page').forEach(function(p){ p.classList.remove('on'); });
  document.querySelectorAll('.nitem').forEach(function(n){ n.classList.remove('on'); });
  var pg = document.getElementById('pg-'+id);
  var ni = document.getElementById('n-'+id);
  if (pg) pg.classList.add('on');
  if (ni) ni.classList.add('on');
  if (id === 'comms')  { renderCommsPage(); }
  if (id === 'social') { renderSocialPage(); }
  if (id === 'adcreative') { renderAdCreativePage(); }
  if (id === 'tasks') {
    // Render banners so user SEES them — don't mark seen yet
    renderNewTaskBanner();
    renderCompletedBanner();
  }
}
function doLogout() {
  curUser = selUid = null; pin = '';
  document.getElementById('app').style.display = 'none';
  var ls = document.getElementById('login-screen');
  ls.style.display = 'flex'; ls.classList.remove('hide');
  document.getElementById('step-pin').style.display = 'none';
  document.getElementById('step-user').style.display = 'block';
  updDots();
}
document.addEventListener('keydown', function(e) {
  if (!selUid) return;
  if (e.key >= '0' && e.key <= '9') pk(e.key);
  if (e.key === 'Backspace') pdel();
});

// ── Dashboard legacy task toggles ──
function togTask(item) {
  var c = item.querySelector('.tck'), t = item.querySelector('.ttx');
  if (!c||!t) return;
  c.classList.toggle('done'); t.classList.toggle('done');
  var u = document.querySelectorAll('#dash-todos .tck:not(.done)').length;
  var b = document.getElementById('todo-ct'); if(b) b.textContent = u;
  saveData();
}

// ── Clients ──
var ATYPES = ['—','1:1 Standard','1:2 Standard','1:3 Standard','1:4 Standard','1:1 Premium','1:2 Premium','1:3 Premium','1:4 Premium','Call Out'];
var CDAYS_OPT = ['—','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
var CONS = ['—','Low','Low/Med','Med','Med/High','High'];
var INVS = ['—','Yes','No','Voucher'];
var cRows = [];
for (var ci=0;ci<30;ci++) cRows.push({name:'',day:'',date:'',type:'',con:'',atts:[],inv:'',notes:''});
var dragFrom = null;

function atypeColor(v) {
  if (!v||v==='—') return '';
  if (v.indexOf('Premium')>-1) return 'color:#7C3AED;font-weight:500';
  if (v.indexOf('Call')>-1) return 'color:#059669;font-weight:500';
  return 'color:#C4956A;font-weight:500';
}
function clearClients() {
  if (!confirm('Clear all 30 slots?')) return;
  for (var ci=0;ci<30;ci++) cRows[ci]={name:'',day:'',date:'',type:'',con:'',atts:[],inv:'',notes:''};
  renderClients();
}

function clearClientRow(i) {
  cRows[i] = {name:'',day:'',date:'',type:'',con:'',atts:[],inv:'',notes:''};
  renderClients();
}
function renderClients() {
  var tb = document.getElementById('ctbody'); if (!tb) return;
  tb.innerHTML = '';
  for (var ci=0;ci<30;ci++) tb.appendChild(makeClientRow(ci));
  updCSummary();
  renderClientContrast();
}

// ── CLIENT PAGE CONTRAST WIDGET ──
var clientContrastTags = {
  skin: { label:'SKIN', val:5, x:0, y:0,   col:'#E05555' },
  hair: { label:'HAIR', val:3, x:0, y:40,  col:'#5578E0' },
  eyes: { label:'EYES', val:7, x:0, y:80,  col:'#42A85F' }
};
var clientContrastDragKey = null, clientContrastDragOX = 0, clientContrastDragOY = 0;
var clientContrastPhoto = null;

function cctLoadPhoto(e) {
  var file = e.target.files[0]; if (!file) return;
  var reader = new FileReader();
  reader.onload = function(ev) {
    clientContrastPhoto = ev.target.result;
    renderClientContrast();
    cctAutoDetect();
  };
  reader.readAsDataURL(file);
}

function cctAutoDetect() {
  if (!clientContrastPhoto || typeof mpAnalyzeContrast !== 'function') return;
  setTimeout(function() {
    var ctn = document.getElementById('client-contrast-preview');
    if (!ctn || !ctn.offsetWidth) return;
    mpShowLoading(ctn);
    mpAnalyzeContrast(clientContrastPhoto, ctn).then(function(result) {
      mpHideLoading(document.getElementById('client-contrast-preview'));
      if (!result) return;
      console.log('[AutoContrast CCT] detected:', JSON.stringify(result));
      clientContrastTags.skin.x = result.skin.x; clientContrastTags.skin.y = result.skin.y;
      clientContrastTags.hair.x = result.hair.x; clientContrastTags.hair.y = result.hair.y;
      clientContrastTags.eyes.x = result.eyes.x; clientContrastTags.eyes.y = result.eyes.y;
      renderClientContrast();
      cctSetVal('skin', result.skin.val);
      cctSetVal('hair', result.hair.val);
      cctSetVal('eyes', result.eyes.val);
    });
  }, 80);
}
function cctClearPhoto() {
  clientContrastPhoto = null;
  var inp = document.getElementById('cct-photo-input');
  if (inp) inp.value = '';
  renderClientContrast();
}

function renderClientContrast() {
  var preview = document.getElementById('client-contrast-preview');
  var controls = document.getElementById('client-contrast-controls');
  if (!preview || !controls) return;

  // Photo — use this widget's own uploaded photo
  var photoHtml = clientContrastPhoto
    ? '<img src="'+clientContrastPhoto+'" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center top;filter:grayscale(100%);display:block;">'
    : '<div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--muted);gap:8px"><div style=\'font-size:32px\'>&#128247;</div><div style=\'font-size:13px\'>Upload a photo above</div></div>';

  var clip = 'polygon(0% 0%, 100% 0%, 100% 20%, 75% 20%, 75% 80%, 100% 80%, 100% 100%, 0% 100%)';
  var greyVals = typeof GREY_VALS !== 'undefined' ? GREY_VALS : [
    {bg:'#111'},{bg:'#222'},{bg:'#333'},{bg:'#444'},{bg:'#555'},
    {bg:'#777'},{bg:'#888'},{bg:'#999'},{bg:'#bbb'},{bg:'#ddd'}
  ];

  // Build tag HTML
  var tagHtml = Object.keys(clientContrastTags).map(function(key) {
    var t = clientContrastTags[key];
    var greyBg = greyVals[t.val - 1].bg;
    var numCol = t.val > 6 ? '#333' : '#fff';
    return '<div id="cct-tag-'+key+'" style="position:absolute;left:'+t.x+'px;top:'+t.y+'px;z-index:10;cursor:move;user-select:none;touch-action:none;display:flex;align-items:center;gap:5px;filter:drop-shadow(0 2px 6px rgba(0,0,0,0.35))"'
      +' onmousedown="cctDragStart(event,\''+key+'\')" ontouchstart="cctTouchStart(event,\''+key+'\')">'
      +'<span style="font-size:8px;font-weight:800;color:'+t.col+';letter-spacing:1.5px;text-transform:uppercase;text-shadow:0 1px 3px rgba(0,0,0,0.6);white-space:nowrap;flex-shrink:0">'+t.label+'</span>'
      +'<div id="cct-swatch-'+key+'" style="position:relative;width:80px;height:36px;border-radius:6px 0 0 6px;background:'+greyBg+';clip-path:'+clip+'">'
      +'<div id="cct-num-'+key+'" style="position:absolute;top:50%;left:35%;transform:translate(-50%,-50%);font-size:10px;font-weight:800;color:'+numCol+';pointer-events:none">'+t.val+'</div>'
      +'</div></div>';
  }).join('');

  preview.innerHTML = photoHtml + tagHtml;

  // Build slider controls
  controls.innerHTML = Object.keys(clientContrastTags).map(function(key) {
    var t = clientContrastTags[key];
    var greyBg = greyVals[t.val - 1].bg;
    return '<div style="background:white;border:1px solid var(--sand);border-radius:10px;padding:14px 16px;margin-bottom:10px">'
      +'<div style="display:flex;align-items:center;gap:10px;margin-bottom:10px">'
      +'<div style="width:14px;height:14px;border-radius:50%;background:'+t.col+';flex-shrink:0"></div>'
      +'<div style="font-size:12px;font-weight:600;color:var(--deep)">'+t.label+'</div>'
      +'<div id="cct-ctrl-swatch-'+key+'" style="margin-left:auto;width:32px;height:20px;border-radius:4px;background:'+greyBg+';border:1px solid var(--sand)"></div>'
      +'<div id="cct-ctrl-num-'+key+'" style="font-size:12px;font-weight:700;color:var(--deep);min-width:16px;text-align:right">'+t.val+'</div>'
      +'</div>'
      +'<input id="cct-slider-'+key+'" type="range" min="1" max="10" value="'+t.val+'" style="width:100%;accent-color:'+t.col+';cursor:pointer" oninput="cctSetVal(\''+key+'\',this.value)">'
      +'<div style="display:flex;justify-content:space-between;margin-top:3px">'
      +'<span style="font-size:9px;color:var(--muted)">Dark 1</span>'
      +'<span style="font-size:9px;color:var(--muted)">Light 10</span>'
      +'</div></div>';
  }).join('');

  cctUpdateResult();
}

function cctSetVal(key, val) {
  val = parseInt(val);
  clientContrastTags[key].val = val;
  var greyVals = typeof GREY_VALS !== 'undefined' ? GREY_VALS : [
    {bg:'#111'},{bg:'#222'},{bg:'#333'},{bg:'#444'},{bg:'#555'},
    {bg:'#777'},{bg:'#888'},{bg:'#999'},{bg:'#bbb'},{bg:'#ddd'}
  ];
  var greyBg = greyVals[val - 1].bg;
  var numCol = val > 6 ? '#333' : '#fff';
  var sw = document.getElementById('cct-swatch-'+key);
  var nm = document.getElementById('cct-num-'+key);
  var csw = document.getElementById('cct-ctrl-swatch-'+key);
  var cnm = document.getElementById('cct-ctrl-num-'+key);
  if (sw) sw.style.background = greyBg;
  if (nm) { nm.textContent = val; nm.style.color = numCol; }
  if (csw) csw.style.background = greyBg;
  if (cnm) cnm.textContent = val;
  var sl = document.getElementById('cct-slider-' + key);
  if (sl) sl.value = val;
  cctUpdateResult();
}

function cctUpdateResult() {
  var vals = Object.keys(clientContrastTags).map(function(k){ return clientContrastTags[k].val; });
  var range = Math.max.apply(null,vals) - Math.min.apply(null,vals);
  var label = range <= 3 ? 'Low Contrast' : range <= 6 ? 'Medium Contrast' : 'High Contrast';
  var t = clientContrastTags;
  var el = document.getElementById('client-contrast-result');
  if (el) el.innerHTML = 'Skin: '+t.skin.val+' · Hair: '+t.hair.val+' · Eyes: '+t.eyes.val+'<br>Range: '+Math.min.apply(null,vals)+'–'+Math.max.apply(null,vals)+' ('+range+' steps) — <strong>'+label+'</strong>';
}

function cctDragStart(e, key) {
  e.preventDefault();
  clientContrastDragKey = key;
  var el = document.getElementById('cct-tag-'+key);
  var prev = document.getElementById('client-contrast-preview');
  if (!el || !prev) return;
  var pr = prev.getBoundingClientRect();
  clientContrastDragOX = e.clientX - pr.left - clientContrastTags[key].x;
  clientContrastDragOY = e.clientY - pr.top - clientContrastTags[key].y;
  document.addEventListener('mousemove', cctDragMove);
  document.addEventListener('mouseup', cctDragEnd);
}
function cctDragMove(e) {
  if (!clientContrastDragKey) return;
  var prev = document.getElementById('client-contrast-preview');
  if (!prev) return;
  var pr = prev.getBoundingClientRect();
  var nx = e.clientX - pr.left - clientContrastDragOX;
  var ny = e.clientY - pr.top - clientContrastDragOY;
  clientContrastTags[clientContrastDragKey].x = nx;
  clientContrastTags[clientContrastDragKey].y = ny;
  var el = document.getElementById('cct-tag-'+clientContrastDragKey);
  if (el) { el.style.left = nx+'px'; el.style.top = ny+'px'; }
}
function cctDragEnd() {
  clientContrastDragKey = null;
  document.removeEventListener('mousemove', cctDragMove);
  document.removeEventListener('mouseup', cctDragEnd);
}
function cctTouchStart(e, key) {
  var touch = e.touches[0];
  clientContrastDragKey = key;
  var prev = document.getElementById('client-contrast-preview');
  if (!prev) return;
  var pr = prev.getBoundingClientRect();
  clientContrastDragOX = touch.clientX - pr.left - clientContrastTags[key].x;
  clientContrastDragOY = touch.clientY - pr.top - clientContrastTags[key].y;
  document.addEventListener('touchmove', cctTouchMove, {passive:false});
  document.addEventListener('touchend', cctDragEnd);
}
function cctTouchMove(e) {
  e.preventDefault();
  if (!clientContrastDragKey) return;
  var touch = e.touches[0];
  var prev = document.getElementById('client-contrast-preview');
  if (!prev) return;
  var pr = prev.getBoundingClientRect();
  var nx = touch.clientX - pr.left - clientContrastDragOX;
  var ny = touch.clientY - pr.top - clientContrastDragOY;
  clientContrastTags[clientContrastDragKey].x = nx;
  clientContrastTags[clientContrastDragKey].y = ny;
  var el = document.getElementById('cct-tag-'+clientContrastDragKey);
  if (el) { el.style.left = nx+'px'; el.style.top = ny+'px'; }
}
function makeClientRow(i) {
  var d = cRows[i];
  var tr = document.createElement('tr');
  tr.setAttribute('draggable','true');
  (function(idx,row){
    row.addEventListener('dragstart',function(){dragFrom=idx;row.classList.add('dragging');});
    row.addEventListener('dragend',function(){row.classList.remove('dragging');});
    row.addEventListener('dragover',function(e){e.preventDefault();row.classList.add('dragover');});
    row.addEventListener('dragleave',function(){row.classList.remove('dragover');});
    row.addEventListener('drop',function(e){
      e.preventDefault();row.classList.remove('dragover');
      if(dragFrom===null||dragFrom===idx)return;
      var m=cRows.splice(dragFrom,1)[0];cRows.splice(idx,0,m);dragFrom=null;renderClients();
    });
  })(i,tr);
  var dayOpts = CDAYS_OPT.map(function(v){return '<option'+(v===(d.day||'—')?' selected':'')+'>'+v+'</option>';}).join('');
  var typeOpts = ATYPES.map(function(v){return '<option'+(v===(d.type||'—')?' selected':'')+' style="'+atypeColor(v)+'">'+v+'</option>';}).join('');
  var conOpts = CONS.map(function(v){return '<option'+(v===(d.con||'—')?' selected':'')+'>'+v+'</option>';}).join('');
  var invOpts = INVS.map(function(v){return '<option'+(v===(d.inv||'—')?' selected':'')+'>'+v+'</option>';}).join('');
  tr.innerHTML =
    '<td><span class="drag-h" title="Drag to reorder">&#8942;</span></td>'+
    '<td style="text-align:center;color:var(--muted);font-size:11px">'+(i+1)+'</td>'+
    '<td><input class="ci" placeholder="Name" value="'+(d.name||'')+'" onchange="cf('+i+',\'name\',this.value)"></td>'+
    '<td><select class="csel" onchange="cf('+i+',\'day\',this.value)">'+dayOpts+'</select></td>'+
    '<td><input class="ci" type="date" value="'+(d.date||'')+'" onchange="cf('+i+',\'date\',this.value)" style="min-width:115px"></td>'+
    '<td><select class="csel" style="'+atypeColor(d.type||'')+'" onchange="cfType('+i+',this)">'+typeOpts+'</select></td>'+
    '<td><select class="csel" onchange="cf('+i+',\'con\',this.value)">'+conOpts+'</select></td>'+
    '<td><div id="aw-'+i+'"></div><button class="addatt" onclick="addAtt('+i+')">+ Add attendee</button></td>'+
    '<td><select class="csel" onchange="cf('+i+',\'inv\',this.value)">'+invOpts+'</select></td>'+
    '<td><input class="ci" placeholder="Notes..." value="'+(d.notes||'')+'" onchange="cf('+i+',\'notes\',this.value)"></td>'+
    '<td><button class="client-clear-btn" onclick="clearClientRow('+i+')" title="Clear row">&#10005;</button></td>';
  var wrap = tr.querySelector('#aw-'+i);
  (d.atts||[]).forEach(function(a,ai){wrap.appendChild(mkAttRow(i,ai,a.name,a.con));});
  return tr;
}
// Debounced save — waits 1.5s after last keystroke before saving to cloud
var _saveTimer = null;
function debouncedSave() {
  clearTimeout(_saveTimer);
  _saveTimer = setTimeout(function(){ saveData(); }, 1500);
}
function cfType(i,sel){cRows[i].type=sel.value;sel.style=atypeColor(sel.value);updCSummary();debouncedSave();}
function cf(i,f,v){cRows[i][f]=v;updCSummary();debouncedSave();}
function addAtt(i){cRows[i].atts.push({name:'',con:'—'});renderClients();debouncedSave();}
function mkAttRow(ri,ai,name,con){
  var div=document.createElement('div');div.className='attrow';
  var cOpts=CONS.map(function(c){return '<option'+(c===(con||'—')?' selected':'')+'>'+c+'</option>';}).join('');
  div.innerHTML='<input class="ci" placeholder="Name" value="'+(name||'')+'" style="min-width:75px" onchange="sa('+ri+','+ai+',\'name\',this.value)"><select class="csel" onchange="sa('+ri+','+ai+',\'con\',this.value)">'+cOpts+'</select><button class="rematt" onclick="remAtt('+ri+','+ai+')">x</button>';
  return div;
}
function sa(ri,ai,f,v){if(cRows[ri].atts[ai])cRows[ri].atts[ai][f]=v;debouncedSave();}
function remAtt(ri,ai){cRows[ri].atts.splice(ai,1);renderClients();debouncedSave();}
function updCSummary(){
  var t=0,inv=0,v=0,p=0;
  cRows.forEach(function(r){
    if(r.name&&r.name.trim()){t++;if(r.inv==='Yes')inv++;else if(r.inv==='Voucher')v++;else if(r.inv==='No')p++;}
  });
  function s(id,n){var el=document.getElementById(id);if(el)el.textContent=n;}
  s('cs-tot',t);s('cs-inv',inv);s('cs-vou',v);s('cs-pen',p);
}

